#!/usr/bin/env bash
# Conformance against elykseer-ml (the reference), using its docker image:
#
#  1. the test vectors in tests/cpp/conformance_vectors.hpp are regenerated by
#     elykseer-ml and must be identical to the committed ones
#     (utConformance checks that elykseer-cpp writes the same chunks)
#  2. elykseer-ml backs up some files; LXRverify and LXRrestore read its chunks
#     and its XML export (lxr_relkeys -x, lxr_relfiles -x) and must restore
#     identical files
#
#   tests/conformance/check-elykseer-ml.sh [build dir]    default: build
#
# ELYKSEER_ML_IMAGE overrides the image.
set -euo pipefail

# keep the image up-to-date. This is codieplusplus/elykseer-ml:v0.10.2
IMAGE=${ELYKSEER_ML_IMAGE:-codieplusplus/elykseer-ml@sha256:e3065286207306b7dc3fa1c35b1801d9cd0d2f44de722fb6c468d7d0f345702a}
HERE=$(cd "$(dirname "$0")" && pwd)
BUILD=$(cd "${1:-build}" && pwd)
CLI="${BUILD}/src/cpp/cli"
for b in LXRrestore LXRverify; do
    test -x "${CLI}/${b}" || { echo "missing ${CLI}/${b}"; exit 1; }
done

WORK=$(mktemp -d)
trap 'rm -rf "${WORK}"' EXIT

ml() { docker run --rm -i --platform linux/amd64 "${IMAGE}" bash -c "$1"; }

echo "== elykseer-ml image: ${IMAGE}"
docker pull --platform linux/amd64 -q "${IMAGE}" >/dev/null

echo "== test vectors"
"${HERE}/generate.sh" --docker "${IMAGE}" "${WORK}/conformance_vectors.hpp"
# the first line names the elykseer-ml version and commit
if ! diff -u <(tail -n +2 "${HERE}/../cpp/conformance_vectors.hpp") <(tail -n +2 "${WORK}/conformance_vectors.hpp"); then
    echo "the test vectors differ from those generated by elykseer-ml"
    exit 1
fi

echo "== backup with elykseer-ml"
MYID=conformance42
mkdir -p "${WORK}/ml"
# the files are created in the container and copied out with tar (no volume, no uid issues)
ml "set -e
    B=\$PWD/_build/default/bin
    W=\$(mktemp -d); cd \$W
    mkdir -p data/sub chunks
    echo 'hello from elykseer-ml' > data/hello.txt
    head -c 3000000 /dev/urandom > data/sub/random.bin
    head -c 40000 /dev/urandom > 'data/sub/with space.bin'
    F=(data/hello.txt data/sub/random.bin 'data/sub/with space.bin')
    \$B/lxr_backup.exe -x chunks -d db -n 16 -i ${MYID} \"\${F[@]}\" >&2
    \$B/lxr_relkeys.exe -x -d db -i ${MYID} \"\${F[@]}\" > keys.xml
    \$B/lxr_relfiles.exe -x -d db -i ${MYID} \"\${F[@]}\" > files.xml
    tar -cf - data chunks keys.xml files.xml" | tar -C "${WORK}/ml" -xf -

cd "${WORK}/ml"
FILES=(data/hello.txt data/sub/random.bin "data/sub/with space.bin")
FARGS=()
for f in "${FILES[@]}"; do FARGS+=(-f "$f"); done

LOG="${WORK}/cli.log"
run() {
    if ! "$@" >>"${LOG}" 2>&1; then
        echo "failed: $*"; tail -n 40 "${LOG}"; exit 1
    fi
}

echo "== verify and restore with elykseer-cpp"
run "${CLI}/LXRverify" --nogpg -y ${MYID} -x chunks -k keys.xml -b files.xml "${FARGS[@]}"
mkdir -p restore
run "${CLI}/LXRrestore" --nogpg -y ${MYID} -n 16 -x chunks -o restore -k keys.xml -b files.xml "${FARGS[@]}"
for f in "${FILES[@]}"; do
    cmp "$f" "restore/$f"
done

echo "conformance with elykseer-ml passed (${#FILES[@]} files)"
